import{_ as a,o as e,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph EC Performance Journey- Classic vs. Fast EC","description":"","frontmatter":{"title":"Ceph EC Performance Journey- Classic vs. Fast EC","date":"2026-04-20T00:00:00.000Z","updated":"2026-04-21T00:00:00.000Z","tags":["erasure coding","performance tuning","OSD","Fast EC","benchmarking"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.md","filePath":"posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.md","lastUpdated":1780459816000}'),t={name:"posts/2026/Ceph_EC_Performance_Journey_-_Classic_vs._Fast_EC.md"};function s(o,l,n,c,p,u){return e(),i("div",null,[...l[0]||(l[0]=[r('<h2 id="演讲背景" tabindex="-1">演讲背景 <a class="header-anchor" href="#演讲背景" aria-label="Permalink to &quot;演讲背景&quot;">​</a></h2><p>本次演讲由 IBM 高级工程经理主持，实际性能测试工作由其印度团队的工程师 Tejas 完成。演讲聚焦于 Classic EC（经典纠删码）与 Fast EC 在实际硬件环境下的性能对比，以及在测试过程中发现并修复的一个关键内存泄漏问题。</p><h2 id="测试环境" tabindex="-1">测试环境 <a class="header-anchor" href="#测试环境" aria-label="Permalink to &quot;测试环境&quot;">​</a></h2><p><strong>硬件配置：</strong></p><ul><li>存储节点：Dell R760，X5D 节点，共 12 个节点</li><li>测试规模：分别测试 4、8、12 节点三种规模</li><li>每节点配备 24 块磁盘</li><li>OSD 扩展测试：8、16、24 个 OSD</li><li>客户端：Dell R630，作为文件数据路由器，128 GB RAM</li><li>BIOS 配置为 Performance模式</li></ul><p><strong>软件配置：</strong></p><ul><li>Ceph 版本：Squid 19.2.1（Classic EC 基准）</li><li>Ceph 版本：Tentacle 30.1.0（Fast EC 测试版本）</li><li>测试期间禁用 auto scaler、balancer 和 scrubing，确保不同测试轮次之间的公平对比</li></ul><p><strong>测试参数：</strong></p><ul><li>客户端数量：6 个，每个客户端运行 5 个镜像，共约 30 个镜像</li><li>IO depth：1 到 256</li><li>Pool 类型：replica 3 及 EC profile（2+2、4+2、6+2）</li><li>工作负载：100% 读、100% 写、70/30 读写混合</li><li>Block size：4 KB、16 KB、32 KB、64 KB、4 MB</li><li>OSD 数量：6 节点 144 个 OSD；12 节点 288 个 OSD</li></ul><h2 id="ec-plugin-变更" tabindex="-1">EC Plugin 变更 <a class="header-anchor" href="#ec-plugin-变更" aria-label="Permalink to &quot;EC Plugin 变更&quot;">​</a></h2><p>本次测试同步更换了 EC 编码插件，从 Jerasure 切换至新的高性能插件（Tentacle 版本）。原因是 Jerasure 维护活跃度不足，新插件能够提供更好的 EC 优化性能。</p><h2 id="初步测试结果-发现回归问题" tabindex="-1">初步测试结果：发现回归问题 <a class="header-anchor" href="#初步测试结果-发现回归问题" aria-label="Permalink to &quot;初步测试结果：发现回归问题&quot;">​</a></h2><p><strong>16K block size 测试（4+2 EC profile）：</strong></p><ul><li>Fast EC（Tentacle）相比 Classic EC（Squid）延迟约 2ms，性能提升约 60%，表现优异。</li></ul><p><strong>64K block size 测试：</strong></p><ul><li>出现意外回归：Squid Classic EC 的性能反而优于 Tentacle Fast EC。</li><li>这一结果不符合预期，触发了深入调查。</li></ul><h2 id="根因分析-内存泄漏" tabindex="-1">根因分析：内存泄漏 <a class="header-anchor" href="#根因分析-内存泄漏" aria-label="Permalink to &quot;根因分析：内存泄漏&quot;">​</a></h2><p>团队借助 Prometheus、Ceph exporter 等监控工具导出了大量客户端和存储服务器的数据集，并联合 Fast EC 开发团队（Alex、Lee、Bill）共同排查。</p><p><strong>发现问题：</strong></p><ul><li>OSD memory target 设置为 16 GB，但实际 OSD RSS 内存消耗仅约 1 GB，远低于预期。</li><li>这表明存在内存泄漏，存未被正确释放。</li></ul><p><strong>内存泄漏根因：</strong></p><ul><li>在 Fast EC 的实现中，每次写操作包含两个阶段：apply（应用）和 commit（提交）。</li><li>在 commit 阶段，会创建 EC dummy ops，用于将写操作刷入 PG log。</li><li>当 PG 进入 idle 状态时，约 1K 大小的对象残留未被释放，随着时间推移逐渐累积，导致内存持续增长。</li><li>PG log 在Ceph 内部用于区分 backfill 和 recovery 操作。</li></ul><h2 id="修复方案与验证" tabindex="-1">修复方案与验证 <a class="header-anchor" href="#修复方案与验证" aria-label="Permalink to &quot;修复方案与验证&quot;">​</a></h2><p><strong>临时 Workaround：</strong></p><ul><li>强制将 PG 状态从 idle 切换，触发内存刷新，使残留对象得以释放。</li><li>此方案用于测试验证，确认修复方向正确。</li></ul><p><strong>正式 Patch：</strong></p><ul><li>开发团队在 workaround 验证后编写了正式补丁，并以 hot patch 形式应用于测试环境。</li></ul><p><strong>修复后效果：</strong></p><ul><li>OSD 内存消耗恢复至 16 GB 目标值附近，行为正常。</li><li>CPU 使用率从约 780% 下降至约 600%。</li><li>16K block size 下，IOPS 从约 1.2M 提升至约 1.6M，提升约 400K。</li><li>64K block size 的回归问题消失，Fast EC 性能重新超越 Classic EC。</li></ul><h2 id="扩展性验证-12-节点集群" tabindex="-1">扩展性验证：12 节点集群 <a class="header-anchor" href="#扩展性验证-12-节点集群" aria-label="Permalink to &quot;扩展性验证：12 节点集群&quot;">​</a></h2><p>将集群从 6 节点（144 OSD）扩展至 12 节点（288 OSD）后：</p><ul><li>整体吞吐量翻倍，验证了 Ceph scale-out 存储的线性扩展能力。</li><li>Fast EC 与 Classic EC 之间的性能差距也随规模扩大而成比例增大，进一步证明 Fast EC 在大规模集群中的优势更为显著。</li></ul><h2 id="fast-ec-与replica-3-对比" tabindex="-1">Fast EC 与Replica 3 对比 <a class="header-anchor" href="#fast-ec-与replica-3-对比" aria-label="Permalink to &quot;Fast EC 与Replica 3 对比&quot;">​</a></h2><p>修复后，Fast EC（4+2）与 replica 3 的性能对比：</p><ul><li>Fast EC 读性能尚未达到 replica 3 水平，但差距在缩小。</li><li>Ceph 8.1 replica 3 与 9.2 replica 3 之间本身也存在性能提升。</li><li>团队预计后续版本（Tentacle 及后续 umbrella release）将在读性能和写性能上持续改进，逐步接近 replica 3。</li></ul><h2 id="后续计划" tabindex="-1">后续计划 <a class="header-anchor" href="#后续计划" aria-label="Permalink to &quot;后续计划&quot;">​</a></h2><ul><li>当前 12 节点 288 OSD 的完整规模测试仍在进行中。</li><li>针对写性能的优化工作正在推进，预计在下一个 umbrella release 中落地。</li><li>持续关注 Fast EC 在大 block size（64K、4MB）场景下的性能改善。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次性能测试历程揭示了 Fast EC 在实际部署中的一个关键内存泄漏缺陷，并通过系统化的监控数据分析和开发团队协作完成了定位与修复。修复后，Fast EC 在小 block size 场景下相比 Classic EC 有显著性能优势，在大规模集群中优势更为突出，整体上朝着接近 replica 3 读性能的目标稳步推进。</p>',39)])])}const d=a(t,[["render",s]]);export{h as __pageData,d as default};
